//! Repository for PurchaseInvoiceLine entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written PurchaseInvoiceLine SQL (4-layer rule: services orchestrate, repos
//! hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<PurchaseInvoiceLine, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgPool, Row};
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::PurchaseInvoiceLine;

use super::sales_invoice_line_repository::BilledLineRow;

/// Table name for PurchaseInvoiceLine entities
pub const TABLE_NAME: &str = "billing.purchase_invoice_lines";

/// Repository for PurchaseInvoiceLine entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct PurchaseInvoiceLineRepository(
    backbone_orm::GenericCrudRepository<PurchaseInvoiceLine, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for PurchaseInvoiceLineRepository {
    type Target = backbone_orm::GenericCrudRepository<PurchaseInvoiceLine, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl PurchaseInvoiceLineRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a priced Purchase Invoice line insert writes.
///
/// Mirrors the raw column shape rather than the `PurchaseInvoiceLine` entity: `account_id` binds the
/// `expense_account_id` column, and `net_amount` arrives already rounded.
pub struct NewPurchaseInvoiceLineRow<'a> {
    pub id: Uuid,
    pub invoice_id: Uuid,
    /// Bound to the `company_id` column (denormalized from the header so the row passes the
    /// ADR-0008 RLS fence on its own). Required since migration 20260426220010.
    pub company_id: Uuid,
    pub item_id: Uuid,
    /// Bound to the `expense_account_id` column.
    pub account_id: Uuid,
    pub description: Option<&'a str>,
    pub quantity: Decimal,
    pub unit_price: Decimal,
    pub net_amount: Decimal,
}

/// One line's expense account + net, for the `Dr Expense/GR-IR` legs of the A/P post.
pub struct ExpenseAmountRow {
    pub expense_account_id: Uuid,
    pub net_amount: Decimal,
}

/// Hand-written PurchaseInvoiceLine SQL. Lives here (not in the write service) per the module's
/// 4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL.
impl PurchaseInvoiceLineRepository {
    /// Insert one priced line.
    ///
    /// Takes the CALLER'S connection so the line commits with its header in one unit. The caller has
    /// already bound the company on it (`bind_company_on`) — don't re-bind here.
    pub async fn insert_line(
        &self,
        conn: &mut sqlx::PgConnection,
        l: &NewPurchaseInvoiceLineRow<'_>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO billing.purchase_invoice_lines
                (id, invoice_id, company_id, item_id, expense_account_id, description, quantity, unit_price, net_amount)
               VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)"#,
        )
        .bind(l.id).bind(l.invoice_id).bind(l.company_id).bind(l.item_id).bind(l.account_id).bind(l.description)
        .bind(l.quantity).bind(l.unit_price).bind(l.net_amount)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Read the live lines' expense accounts + nets for the A/P post. The caller wraps this in
    /// `with_company_scope(Some(company))` (the company comes off the invoice header) so the read
    /// passes the RLS fence (ADR-0008).
    pub async fn fetch_expense_amounts(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<Vec<ExpenseAmountRow>, sqlx::Error> {
        let rows = company_scope::fetch_all_rows_scoped(
            pool,
            sqlx::query("SELECT expense_account_id, net_amount FROM billing.purchase_invoice_lines WHERE invoice_id=$1 AND (metadata->>'deleted_at') IS NULL")
                .bind(invoice_id),
        )
        .await?;
        Ok(rows.iter().map(|r| ExpenseAmountRow {
            expense_account_id: r.get("expense_account_id"), net_amount: r.get("net_amount"),
        }).collect())
    }

    /// Read the live lines' item + qty for the buying seam. Shares [`BilledLineRow`] with the sales
    /// side — same projection, other table. Caller supplies the company scope, as
    /// [`Self::fetch_expense_amounts`].
    pub async fn fetch_billed_lines(
        &self,
        pool: &PgPool,
        invoice_id: Uuid,
    ) -> Result<Vec<BilledLineRow>, sqlx::Error> {
        let rows = company_scope::fetch_all_rows_scoped(
            pool,
            sqlx::query("SELECT item_id, quantity FROM billing.purchase_invoice_lines WHERE invoice_id=$1 AND (metadata->>'deleted_at') IS NULL")
                .bind(invoice_id),
        )
        .await?;
        Ok(rows.iter().map(|r| BilledLineRow {
            item_id: r.get("item_id"), quantity: r.get("quantity"),
        }).collect())
    }

    /// Transaction-accepting twin of [`Self::fetch_billed_lines`] (outbox fence).
    pub async fn fetch_billed_lines_on(
        &self,
        conn: &mut sqlx::PgConnection,
        invoice_id: Uuid,
    ) -> Result<Vec<BilledLineRow>, sqlx::Error> {
        let rows: Vec<sqlx::postgres::PgRow> = sqlx::query(
            "SELECT item_id, quantity FROM billing.purchase_invoice_lines WHERE invoice_id=$1 AND (metadata->>'deleted_at') IS NULL",
        )
        .bind(invoice_id)
        .fetch_all(conn)
        .await?;
        Ok(rows.iter().map(|r| BilledLineRow {
            item_id: r.get("item_id"), quantity: r.get("quantity"),
        }).collect())
    }
}

backbone_core::impl_crud_repository!(PurchaseInvoiceLineRepository, PurchaseInvoiceLine, soft_delete);
